"use client";

import { useState, useEffect, useRef } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Slider } from "@/components/ui/slider";
import { TrendingUp, Wallet, Coins, Bot } from "lucide-react";
import dynamic from 'next/dynamic';
import { Skeleton } from '@/components/ui/skeleton';
import type { GetForexAnalysisInput, GetForexAnalysisOutput } from '@/ai/schemas';
import TrendingTokensCard from '@/components/trading/TrendingTokensCard';
import BacktestSimulator from '@/components/trading/BacktestSimulator';
import AIAnalysisConsoleCard from '@/components/ai/AIAnalysisConsoleCard';
import AIAnalysisHistoryTable from '@/components/ai/AIAnalysisHistoryTable';
import { cn, formatSolToUsdAndHtg, formatUsdToHtg } from '@/lib/utils';
import { useAppState } from '@/context/AppContext';
import { getRealSolanaBalance } from '@/services/pumpFunService';
import { currencyPairs as allCurrencyPairs, timeframes as allTimeframes } from '@/hooks/useTradingSimulation';
const AutomatedPipelineFlowVisualizer = dynamic(
  () => import('@/components/trading/AutomatedPipelineFlowVisualizer').then((mod) => mod.default),
  { ssr: false }
);

const TVWidget = dynamic(
  () => import('@/components/trading/TradingViewWidget').then((mod) => mod.default),
  {
    ssr: false,
    loading: () => <Skeleton className="h-full w-full bg-white/5" />,
  }
);

const defaultCurrencyPairs = allCurrencyPairs.filter((c: any) => c.value !== 'ALL');
const solanaRealPairs = [
  { value: 'SOL', label: 'SOL/USD (Solana Native)', ticker: 'SOL-USD' },
  { value: 'SOL:$WIF', label: '$WIF (dogwifhat Solana)', ticker: 'WIF-USD' },
  { value: 'SOL:$BONK', label: '$BONK (Bonk Solana)', ticker: 'BONK-USD' },
  { value: 'SOL:$TRUMP', label: '$TRUMP (Official Trump)', ticker: 'TRUMP-USD' },
  { value: 'SOL:RAYDIUM', label: 'RAY/SOL (Raydium Migration)', ticker: 'RAY-USD' }
];

export default function ForexAnalysisPage() {
  const { tradingMode, balance, closedPositions, bots } = useAppState();
  const currencyPairs = tradingMode === 'REAL' ? solanaRealPairs : defaultCurrencyPairs;
  const [pair, setPair] = useState(currencyPairs[0].value);
  const [timeframe, setTimeframe] = useState(allTimeframes[2].value);
  const [selectedIndicators, setSelectedIndicators] = useState<string[]>(["RSI", "SMA", "Volume Profile (POC)"]);
  const [analysis, setAnalysis] = useState<GetForexAnalysisOutput | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const chartApiRef = useRef<any>(null);
  const [isClient, setIsClient] = useState(false);
  const [isChartReady, setIsChartReady] = useState(false);
  const [debateLogs, setDebateLogs] = useState<{ agent: string; msg: string; color: string }[]>([]);

  const [walletAsset, setWalletAsset] = useState("SOL");
  const [walletAction, setWalletAction] = useState("Exchange");
  const [walletAmount, setWalletAmount] = useState(45);
  const [solanaBalance, setSolanaBalance] = useState<number | null>(null);
  const [tradeHistory, setTradeHistory] = useState<any[]>([]);

  useEffect(() => {
    setIsClient(true);
    if (tradingMode === 'REAL') {
      getRealSolanaBalance().then(res => {
        if (res && res.success && res.balance !== undefined) {
          setSolanaBalance(res.balance);
        }
      });
    }
  }, [tradingMode]);

  const handleAnalysis = async () => {
    const chart = chartApiRef.current;
    if (!chart) {
      setError("Le graphique de trading n'est pas encore prêt. Veuillez patienter.");
      return;
    }

    setIsLoading(true);
    setError(null);
    setDebateLogs([]);

    const selectedPairLabel = currencyPairs.find(p => p.value === pair)?.label || pair;
    const selectedTimeframeLabel = allTimeframes.find(t => t.value === timeframe)?.label || timeframe;

    const dialogueSteps = [
      { agent: "Agent Math (Indicateurs)", msg: `Chargement des Klines sur ${selectedPairLabel}...`, color: "text-cyan-400" },
      { agent: "Agent Chart (Tendance)", msg: "Analyse visuelle des chandeliers par Gemini.", color: "text-[#c2ff0c]" },
      { agent: "Agent Risk (Volatilité)", msg: "Calcul du Stop Loss optimal. Levier max 10x.", color: "text-rose-400" },
      { agent: "Syndicate Executive", msg: "Consensus approuvé par les agents.", color: "text-purple-400" }
    ];

    let index = 0;
    setDebateLogs([dialogueSteps[0]]);
    const intervalId = setInterval(() => {
      index++;
      if (index < dialogueSteps.length) {
        setDebateLogs(prev => [...prev, dialogueSteps[index]]);
      } else {
        clearInterval(intervalId);
      }
    }, 1200);

    try {
      const rawCanvas = await chart.takeScreenshot();
      const compressedCanvas = document.createElement('canvas');
      const ratio = Math.min(900 / rawCanvas.width, 500 / rawCanvas.height);
      const w = Math.round(rawCanvas.width * ratio);
      const h = Math.round(rawCanvas.height * ratio);
      compressedCanvas.width = w;
      compressedCanvas.height = h;
      const ctx = compressedCanvas.getContext('2d');
      if (ctx) ctx.drawImage(rawCanvas, 0, 0, w, h);
      const chartScreenshot = compressedCanvas.toDataURL('image/jpeg', 0.7);

      const input: GetForexAnalysisInput = {
        pair: selectedPairLabel,
        timeframe: selectedTimeframeLabel,
        chartScreenshot,
        indicators: selectedIndicators,
      };

      const apiRes = await fetch('/api/analysis', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(input),
      });

      if (!apiRes.ok) {
        const errData = await apiRes.json().catch(() => ({}));
        throw new Error(errData.error || "Erreur lors de l'analyse IA.");
      }

      const result: GetForexAnalysisOutput = await apiRes.json();
      clearInterval(intervalId);
      setDebateLogs(dialogueSteps);
      setAnalysis(result);

      const now = new Date();
      const dateStr = now.toLocaleDateString('fr-FR', { day: '2-digit', month: 'short' }) +
        `, ${now.toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' })}`;

      setTradeHistory(prev => [{
        date: dateStr,
        pair: selectedPairLabel,
        trend: result.trend,
        signal: result.signal,
        justification: result.justification,
        value: result.signal === 'NEUTRE' ? '$0.00' : '$1,500.00',
        status: result.signal === 'NEUTRE' ? 'En cours' : 'Gagné'
      }, ...prev]);
    } catch (e: any) {
      clearInterval(intervalId);
      setError(e.message || "Erreur lors de l'analyse.");
    } finally {
      setIsLoading(false);
    }
  };

  const botTrades = closedPositions.filter(p => p.wasBot);
  const winRate = botTrades.length > 0
    ? `${Math.round((botTrades.filter(t => t.profit >= 0).length / botTrades.length) * 100)}%`
    : "0%";

  return (
    <div className="space-y-6 pb-12" suppressHydrationWarning>
      {/* Visualiseur de Pipeline d'Exécution IA & Solana */}
      <AutomatedPipelineFlowVisualizer />
      {/* Top Header */}
      <div className="flex flex-col md:flex-row items-start md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold tracking-tight text-white font-headline">
            Analyse Visuelle IA
          </h1>
          <p className="text-sm text-white/50 font-body mt-1">
            Analyse de marché Forex en temps réel combinée à l'intelligence artificielle Gemini.
          </p>
        </div>

        <div className="flex items-center gap-4 bg-white/5 border border-white/10 rounded-2xl p-2.5 pr-4">
          <div className="p-2.5 rounded-xl bg-[#c2ff0c]/15 text-[#c2ff0c]">
            <TrendingUp className="h-5 w-5" />
          </div>
          <div>
            <p className="text-[10px] text-white/40 uppercase tracking-wider font-bold">
              {tradingMode === 'REAL' ? 'Solde SOL Réel' : 'Solde Démo USD'}
            </p>
            <p className="text-lg font-bold font-mono text-white leading-none mt-1">
              {tradingMode === 'REAL' 
                ? `${solanaBalance !== null ? solanaBalance.toFixed(2) : '0.00'} SOL`
                : `${balance.toLocaleString('fr-FR', { minimumFractionDigits: 2 })} $`
              }
            </p>
          </div>
        </div>
      </div>

      {/* Main Interactive Grid */}
      <div className="grid grid-cols-1 xl:grid-cols-3 gap-6">
        <Card className="xl:col-span-2 glass-panel border-white/5 shadow-xl h-[520px] flex flex-col overflow-hidden">
          <CardHeader className="pb-3 flex flex-row items-center justify-between">
            <div>
              <CardTitle className="font-headline text-lg text-white">Graphique Direct</CardTitle>
              <CardDescription className="text-white/40 text-xs font-body">TradingView Live Feed</CardDescription>
            </div>
          </CardHeader>
          <CardContent className="p-0 flex-grow relative">
            {isClient && <TVWidget 
              symbol={pair} 
              interval={timeframe} 
              indicators={selectedIndicators}
              onReady={(chart) => {
                chartApiRef.current = chart;
                setIsChartReady(true);
              }}
            />}
          </CardContent>
        </Card>

        {/* AI Console Component */}
        <AIAnalysisConsoleCard
          pair={pair}
          setPair={setPair}
          timeframe={timeframe}
          setTimeframe={setTimeframe}
          currencyPairs={currencyPairs}
          timeframes={allTimeframes}
          selectedIndicators={selectedIndicators}
          setSelectedIndicators={setSelectedIndicators}
          handleAnalysis={handleAnalysis}
          isChartReady={isChartReady}
          isLoading={isLoading}
          error={error}
          debateLogs={debateLogs}
          analysis={analysis}
        />
      </div>

      {/* Bottom Grid Cards */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <TrendingTokensCard />

        <Card className="glass-panel border-white/5 shadow-xl flex flex-col justify-between overflow-hidden">
          <CardHeader className="pb-3">
            <CardTitle className="font-headline text-lg text-white flex items-center gap-2">
              <Bot className="h-5 w-5 text-[#c2ff0c]" />
              <span>Statistiques IA</span>
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4 pt-2">
            <div className="grid grid-cols-2 gap-3 text-center">
              <div className="p-3.5 rounded-xl bg-white/5 border border-white/5">
                <p className="text-[9px] text-white/30 font-bold uppercase font-headline">Réussite</p>
                <p className="text-xl font-bold font-mono text-green-400 mt-1">{winRate}</p>
              </div>
              <div className="p-3.5 rounded-xl bg-white/5 border border-white/5">
                <p className="text-[9px] text-white/30 font-bold uppercase font-headline">Trades</p>
                <p className="text-xl font-bold font-mono text-white mt-1">{botTrades.length}</p>
              </div>
            </div>
          </CardContent>
        </Card>

        <BacktestSimulator />
      </div>

      {/* History Table Component */}
      <AIAnalysisHistoryTable
        tradeHistory={tradeHistory}
        closedPositions={closedPositions}
      />
    </div>
  );
}

"use client";

import React, { useState, useEffect } from 'react';
import { ArrowDownLeft, Copy, Check, Lock, Wallet, RefreshCw, AlertCircle, Edit2, ExternalLink } from 'lucide-react';
import { cn, formatSolToUsdAndHtg, formatUsdToHtg } from '@/lib/utils';
import { getRealSolanaBalance, fetchLiveWalletBalance } from '@/services/pumpFunService';
import { useAppState } from '@/context/AppContext';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent } from '@/components/ui/card';
import TransactionHistoryTable from '@/components/trading/TransactionHistoryTable';
import DepositGuidesCard from '@/components/wallet/DepositGuidesCard';
import ReserveVaultCard from '@/components/wallet/ReserveVaultCard';

const SOL_EXPLORER = 'https://solscan.io/account/';
const MANUAL_SOL_KEY = 'manual_solana_deposit_address';

export default function DepositPage() {
  const { tradingMode, setTradingMode, balance, setBalance, reserveVault, setReserveVault, reserveVaultSol, setReserveVaultSol, transactions, setTransactions } = useAppState();
  const [solanaPubKey, setSolanaPubKey] = useState<string>('');
  const [solanaBalance, setSolanaBalance] = useState<number | null>(null);
  const [evmAddress, setEvmAddress] = useState<string>('');
  const [walletChain, setWalletChain] = useState<string>('');
  const [isCopied, setIsCopied] = useState(false);
  const [depositAmount, setDepositAmount] = useState<string>('1000');
  const [vaultUnlockAmount, setVaultUnlockAmount] = useState<string>('');
  const [isUnlockingVault, setIsUnlockingVault] = useState<boolean>(false);
  const [isLoading, setIsLoading] = useState(false);
  const [isMounted, setIsMounted] = useState(false);
  const [isEditingAddress, setIsEditingAddress] = useState(false);
  const [manualAddress, setManualAddress] = useState<string>('');

  useEffect(() => { setIsMounted(true); }, []);

  const refreshLiveBalance = () => {
    if (tradingMode === 'REAL') {
      fetchLiveWalletBalance().then(res => {
        if (res && res.success) {
          if (res.solanaBalance !== null) setSolanaBalance(res.solanaBalance);
          if (res.solanaPubKey && !solanaPubKey) setSolanaPubKey(res.solanaPubKey);
          if (res.walletChain) setWalletChain(res.walletChain);
        }
      });
    }
  };

  useEffect(() => {
    if (!isMounted) return;

    // 1. Load connected Web3 wallet from localStorage
    const stored = localStorage.getItem('connected_web3_wallet');
    if (stored) {
      try {
        const parsed = JSON.parse(stored) as { address: string; chain: string; name: string };
        setWalletChain(parsed.chain);
        if (parsed.chain === 'Solana') {
          setSolanaPubKey(parsed.address);
        } else {
          setEvmAddress(parsed.address);
        }
      } catch (e) {}
    }

    // 2. Load manually set SOL deposit address
    const manualAddr = localStorage.getItem(MANUAL_SOL_KEY);
    if (manualAddr) {
      setManualAddress(manualAddr);
      const storedWallet = localStorage.getItem('connected_web3_wallet');
      if (!storedWallet || JSON.parse(storedWallet || '{}').chain !== 'Solana') {
        setSolanaPubKey(manualAddr);
      }
    }

    // 3. Get live balance from connected wallet or keypair
    refreshLiveBalance();

    const handleWalletUpdated = () => refreshLiveBalance();
    window.addEventListener('web3_wallet_updated', handleWalletUpdated);
    return () => window.removeEventListener('web3_wallet_updated', handleWalletUpdated);
  }, [tradingMode, isMounted]);

  const handleCopyAddress = () => {
    const addr = solanaPubKey || manualAddress;
    if (!addr) return;
    navigator.clipboard.writeText(addr);
    setIsCopied(true);
    setTimeout(() => setIsCopied(false), 2000);
  };

  const handleSaveManualAddress = () => {
    const trimmed = manualAddress.trim();
    if (!trimmed) return;
    localStorage.setItem(MANUAL_SOL_KEY, trimmed);
    setSolanaPubKey(trimmed);
    setIsEditingAddress(false);
  };

  const handleUnlockVault = (e: React.FormEvent) => {
    e.preventDefault();
    const isReal = tradingMode === 'REAL';
    const currentVault = isReal ? (Number(reserveVaultSol) || 0) : (Number(reserveVault) || 0);
    const amt = parseFloat(vaultUnlockAmount) || currentVault;
    if (amt <= 0 || amt > currentVault) return;
    setIsUnlockingVault(true);
    setTimeout(() => {
      if (isReal) {
        setReserveVaultSol(prev => Math.max(0, prev - amt));
      } else {
        setReserveVault(prev => Math.max(0, prev - amt));
        setBalance(prev => prev + amt);
      }
      setTransactions(prev => [{
        id: 'tx_vault_' + Math.random().toString(36).substring(2, 9),
        type: 'DEPOSIT' as const,
        amount: amt,
        currency: isReal ? 'SOL' : 'USD',
        timestamp: Date.now(),
        status: 'COMPLETED'
      }, ...(prev || [])]);
      setIsUnlockingVault(false);
      setVaultUnlockAmount('');
    }, 600);
  };

  const handleDemoDeposit = (e: React.FormEvent) => {
    e.preventDefault();
    if (tradingMode === 'REAL') return;
    const amt = parseFloat(depositAmount);
    if (isNaN(amt) || amt <= 0) return;
    setIsLoading(true);
    setTimeout(() => {
      setBalance(balance + amt);
      setTransactions(prev => [{
        id: 'tx_' + Math.random().toString(36).substring(2, 9),
        type: 'DEPOSIT' as const,
        amount: amt,
        currency: 'USD',
        timestamp: Date.now(),
        status: 'COMPLETED'
      }, ...(prev || [])]);
      setIsLoading(false);
      setDepositAmount('1000');
    }, 500);
  };

  const currentTxs = (transactions || []).filter(tx =>
    tradingMode === 'REAL' ? tx.currency === 'SOL' : tx.currency === 'USD'
  );

  const displayAddress = solanaPubKey || manualAddress;

  return (
    <div className="space-y-8 max-w-5xl mx-auto p-4 md:p-6 text-white" suppressHydrationWarning>
      {/* Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 border-b border-white/5 pb-5">
        <div>
          <h1 className="text-3xl font-bold tracking-tight font-headline flex items-center gap-2">
            <ArrowDownLeft className="h-8 w-8 text-[#c2ff0c]" />
            Créditer le Compte
          </h1>
          <p className="text-sm text-white/40 mt-1 font-body">Alimentez vos fonds pour la simulation ou le trading réel.</p>
        </div>

        <div className="flex items-center bg-black/40 border border-white/10 p-1.5 rounded-xl gap-1 shrink-0">
          <Button
            variant="ghost"
            onClick={() => setTradingMode('DEMO')}
            className={cn("px-4 py-2 h-9 text-xs font-extrabold uppercase rounded-lg transition-all duration-200 font-headline flex items-center gap-2 border-none cursor-pointer",
              tradingMode === 'DEMO' ? "bg-amber-500/20 text-amber-300 border border-amber-500/40 shadow-sm font-black" : "text-white/40 hover:text-white hover:bg-white/5")}
          >
            <span className="h-2 w-2 rounded-full bg-amber-400" />
            Mode Démo
          </Button>
          <Button
            variant="ghost"
            onClick={() => setTradingMode('REAL')}
            className={cn("px-4 py-2 h-9 text-xs font-extrabold uppercase rounded-lg transition-all duration-200 font-headline flex items-center gap-2 border-none cursor-pointer",
              tradingMode === 'REAL' ? "bg-purple-600/25 text-purple-200 border border-purple-500/40 shadow-sm font-black" : "text-white/40 hover:text-white hover:bg-white/5")}
          >
            <span className="h-2 w-2 rounded-full bg-purple-400 animate-pulse" />
            Mode Réel (Solana)
          </Button>
        </div>
      </div>

      {/* Account Balance Overview Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <Card className="bg-[#14101a] border-white/10 rounded-2xl p-5 space-y-2 relative overflow-hidden shadow-xl">
          <span className="text-[10px] uppercase font-bold text-[#c2ff0c] font-headline block">Solde Actuel Disponible</span>
