"use client";

import React, { useState, useEffect } from 'react';
import { TrendingUp, Bot, ShieldCheck, Target, Flame, RefreshCw } from 'lucide-react';
import { cn, formatSolToUsdAndHtg, formatUsdToHtg, formatSmartPnl } from '@/lib/utils';
import { useAppState } from '@/context/AppContext';
import PerformanceStrategyCard from '@/components/layout/PerformanceStrategyCard';

export default function PerformancePage() {
  const { tradingMode, setTradingMode, bots, closedPositions } = useAppState();
  const [isMounted, setIsMounted] = useState(false);

  useEffect(() => {
    setIsMounted(true);
  }, []);

  const getBotStats = (strategyName: string, pumpMode?: string) => {
    const matchingBots = bots.filter(b => {
      if (b.strategy !== strategyName) return false;
      if (pumpMode && b.pumpMode !== pumpMode) return false;
      return true;
    });

    const botIds = matchingBots.map(b => b.id);
    const matchingTrades = closedPositions.filter(p => {
      if (!p) return false;
      const tradeMode = p.mode || (p.pair?.startsWith('SOL:') ? 'REAL' : 'DEMO');
      if (tradeMode !== tradingMode) return false;
      if (p.botId && botIds.includes(p.botId)) return true;
      if (p.botName && p.botName.toLowerCase().includes(strategyName.toLowerCase())) return true;
      return false;
    });

    const totalProfit = matchingTrades.reduce((sum, t) => {
      const p = typeof t.profit === 'number' && !isNaN(t.profit) ? t.profit : 0;
      if (Math.abs(p) > 100000) return sum;
      return sum + p;
    }, 0);
    const totalTrades = matchingTrades.length;
    const winningTrades = matchingTrades.filter(t => (t.profit || 0) >= 0).length;
    const winRate = totalTrades > 0 ? `${Math.round((winningTrades / totalTrades) * 100)}%` : "0%";
    const isActive = matchingBots.some(b => b.status === 'RUNNING');
    const isReal = tradingMode === 'REAL';

    const totalAllocatedCapital = matchingBots.reduce((sum, b) => sum + (b.capital || 0), 0);
    let yieldPercent = "0.0%";
    if (totalAllocatedCapital > 0) {
      const yieldVal = (totalProfit / totalAllocatedCapital) * 100;
      yieldPercent = yieldVal >= 0 ? `+${yieldVal.toFixed(1)}%` : `${yieldVal.toFixed(1)}%`;
    }

    const netGains = (
      <div className="flex flex-col">
        <span>{isReal ? `${totalProfit >= 0 ? '+' : ''}${formatSmartPnl(totalProfit, true)} SOL` : `${totalProfit >= 0 ? '+' : ''}${formatSmartPnl(totalProfit, false)} $`}</span>
        <span className="text-[9px] text-white/40 font-mono font-normal">
          {isReal ? formatSolToUsdAndHtg(totalProfit).combinedLabel : `≈ ${formatUsdToHtg(totalProfit)}`}
        </span>
      </div>
    );

    return {
      profit: yieldPercent,
      netGains,
      winRate,
      status: isActive ? "ACTIF" : (matchingBots.length > 0 ? "PAUSE" : "INACTIF")
    };
  };

  const autopilotStats = getBotStats('AI Autopilot (Machine à Cash)');
  const rsiStats = getBotStats('RSI Pullback');
  const emaStats = getBotStats('EMA Cross');

  const precoceStats = getBotStats('Pump.fun Sniper Bot', 'PRECOCE');
  const momentumStats = getBotStats('Pump.fun Sniper Bot', 'MOMENTUM');
  const raydiumStats = getBotStats('Pump.fun Sniper Bot', 'RAYDIUM');

  const strategiesList = tradingMode === 'DEMO' ? [
    {
      name: "IA Autopilot (Machine à Cash)",
      description: "Apprentissage continu sur Forex/Crypto.",
      profit: autopilotStats.profit,
      netGains: autopilotStats.netGains,
      winRate: autopilotStats.winRate,
      risk: "MODÉRÉ",
      status: autopilotStats.status,
      color: "text-[#c2ff0c]",
      barColor: "bg-[#c2ff0c]",
      icon: Bot
    },
    {
      name: "RSI Pullback Reversal",
      description: "Détection des extrêmes de survente/surachat.",
      profit: rsiStats.profit,
      netGains: rsiStats.netGains,
      winRate: rsiStats.winRate,
      risk: "SÛR",
      status: rsiStats.status,
      color: "text-emerald-400",
      barColor: "bg-emerald-400",
      icon: ShieldCheck
    },
    {
      name: "EMA Golden Cross Trend",
      description: "Suivi de tendance via croisements d'exponentielles.",
      profit: emaStats.profit,
      netGains: emaStats.netGains,
      winRate: emaStats.winRate,
      risk: "MODÉRÉ",
      status: emaStats.status,
      color: "text-cyan-400",
      barColor: "bg-cyan-400",
      icon: Target
    }
  ] : [
    {
      name: "Solana Sniper (Ultra-Précoce)",
      description: "Achat dès l'émission de la bonding curve.",
      profit: precoceStats.profit,
      netGains: precoceStats.netGains,
      winRate: precoceStats.winRate,
      risk: "ÉLEVÉ",
      status: precoceStats.status,
      color: "text-purple-400",
      barColor: "bg-purple-500",
      icon: Flame
    },
    {
      name: "Solana Sniper (Momentum)",
      description: "Achat sur accélération de momentum social.",
      profit: momentumStats.profit,
      netGains: momentumStats.netGains,
      winRate: momentumStats.winRate,
      risk: "MODÉRÉ",
      status: momentumStats.status,
      color: "text-[#c2ff0c]",
      barColor: "bg-[#c2ff0c]",
      icon: Bot
    },
    {
      name: "Raydium Migration Frontrun",
      description: "Achat sur migrations Raydium imminentes.",
      profit: raydiumStats.profit,
      netGains: raydiumStats.netGains,
      winRate: raydiumStats.winRate,
      risk: "SÛR",
      status: raydiumStats.status,
      color: "text-cyan-400",
      barColor: "bg-cyan-400",
      icon: ShieldCheck
    }
  ];

  return (
    <div className="space-y-6 max-w-5xl mx-auto p-4 md:p-6 text-white" suppressHydrationWarning>
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 border-b border-white/5 pb-5">
        <div>
          <h1 className="text-3xl font-bold tracking-tight font-headline flex items-center gap-2">
            <TrendingUp className="h-8 w-8 text-[#c2ff0c]" />
            Comparatif des Performances
          </h1>
          <p className="text-sm text-white/40 mt-1 font-body">Analysez et comparez l'efficacité de vos stratégies.</p>
        </div>

        <div className="flex items-center bg-white/5 border border-white/10 p-1 rounded-xl gap-1 shrink-0">
          <button onClick={() => setTradingMode('DEMO')} className={cn("px-3.5 py-1.5 text-[10px] font-bold uppercase rounded-lg font-headline", tradingMode === 'DEMO' ? "bg-amber-500/25 text-amber-300" : "text-white/40")}>
            Mode Démo
          </button>
          <button onClick={() => setTradingMode('REAL')} className={cn("px-3.5 py-1.5 text-[10px] font-bold uppercase rounded-lg font-headline", tradingMode === 'REAL' ? "bg-purple-600/25 text-purple-300" : "text-white/40")}>
            Mode Réel (Solana)
          </button>
        </div>
      </div>

      <div className="space-y-4">
        {strategiesList.map(strat => (
          <PerformanceStrategyCard key={strat.name} strategy={strat} />
        ))}
      </div>
    </div>
  );
}

"use client";

import React, { useState, useEffect } from 'react';
import { ArrowUpRight, RefreshCw } from 'lucide-react';
import { cn, formatSolToUsdAndHtg, formatUsdToHtg } from '@/lib/utils';
import { getRealSolanaBalance, withdrawSolana, fetchLiveWalletBalance } from '@/services/pumpFunService';
import { useAppState } from '@/context/AppContext';
import { Button } from '@/components/ui/button';
import { Card } from '@/components/ui/card';
import TransactionHistoryTable from '@/components/trading/TransactionHistoryTable';
import WithdrawFormCard from '@/components/wallet/WithdrawFormCard';
import ReserveVaultCard from '@/components/wallet/ReserveVaultCard';

const SOLANA_NETWORK_FEE = 0.00005;
const PRIORITY_FEE_ESTIMATE = 0.001;

export default function WithdrawPage() {
  const { tradingMode, setTradingMode, balance, setBalance, transactions, setTransactions } = useAppState();
  const [solanaPubKey, setSolanaPubKey] = useState<string>('');
  const [solanaBalance, setSolanaBalance] = useState<number | null>(null);

  const [recipientAddress, setRecipientAddress] = useState('');
  const [withdrawAmount, setWithdrawAmount] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [txHash, setTxHash] = useState('');
  const [errorMsg, setErrorMsg] = useState('');
  const [isMounted, setIsMounted] = useState(false);
  const [connectedWeb3Wallet, setConnectedWeb3Wallet] = useState<{ name: string; address: string; chain: string } | null>(null);

  const refreshLiveBalance = () => {
    if (tradingMode === 'REAL') {
      fetchLiveWalletBalance().then(res => {
        if (res && res.success) {
          if (res.solanaBalance !== null) setSolanaBalance(res.solanaBalance);
          if (res.solanaPubKey && !solanaPubKey) setSolanaPubKey(res.solanaPubKey);
        }
      });
    }
  };

  useEffect(() => {
    if (typeof window !== 'undefined') {
      const stored = localStorage.getItem('connected_web3_wallet');
      if (stored) {
        try { setConnectedWeb3Wallet(JSON.parse(stored)); } catch (e) {}
      }
    }
    setIsMounted(true);
  }, []);

  useEffect(() => {
    if (!isMounted || tradingMode !== 'REAL') return;
    refreshLiveBalance();

    const handleWalletUpdated = () => refreshLiveBalance();
    window.addEventListener('web3_wallet_updated', handleWalletUpdated);
    return () => window.removeEventListener('web3_wallet_updated', handleWalletUpdated);
  }, [tradingMode, isMounted]);

  const handleFillConnectedWeb3Address = async () => {
    if (connectedWeb3Wallet && connectedWeb3Wallet.address) {
      setRecipientAddress(connectedWeb3Wallet.address);
      return;
    }
    try {
      const win = window as any;
      const solanaObj = win.solana || win.solflare || win.backpack;
      if (solanaObj) {
        const resp = await solanaObj.connect();
        const pubKey = resp?.publicKey ? resp.publicKey.toString() : solanaObj.publicKey?.toString();
        if (pubKey) {
          const providerName = solanaObj.isPhantom ? "Phantom Solana" : "Solana Web3 Wallet";
          const w = { name: providerName, address: pubKey, chain: "Solana" };
          localStorage.setItem('connected_web3_wallet', JSON.stringify(w));
          setConnectedWeb3Wallet(w);
          setRecipientAddress(pubKey);
        }
      }
    } catch (err: any) {}
  };

  const handlePercentClick = (pct: number) => {
    const maxAvailable = tradingMode === 'REAL'
      ? Math.max(0, (solanaBalance || 0) - SOLANA_NETWORK_FEE - PRIORITY_FEE_ESTIMATE)
      : balance;
    if (maxAvailable <= 0) { setWithdrawAmount('0'); return; }
    const decimals = tradingMode === 'REAL' ? 4 : 2;
    setWithdrawAmount((maxAvailable * (pct / 100)).toFixed(decimals));
  };

  const handleWithdraw = async (e: React.FormEvent) => {
    e.preventDefault();
    setErrorMsg('');
    setTxHash('');
    const amt = parseFloat(withdrawAmount);
    if (isNaN(amt) || amt <= 0) { setErrorMsg("Veuillez entrer un montant valide supérieur à 0."); return; }
    setIsLoading(true);

    if (tradingMode === 'DEMO') {
      setTimeout(() => {
        if (amt > balance) { setErrorMsg("Solde insuffisant."); setIsLoading(false); return; }
        setBalance(balance - amt);
        setTransactions(prev => [{
          id: 'tx_' + Math.random().toString(36).substring(2, 9),
          type: 'WITHDRAW' as const,
          amount: amt,
          currency: 'USD',
          timestamp: Date.now(),
          status: 'COMPLETED'
        }, ...(prev || [])]);
        setIsLoading(false);
        setWithdrawAmount('');
      }, 600);
    } else {
      if (!recipientAddress) { setErrorMsg("Adresse destinataire requise."); setIsLoading(false); return; }
      try {
        const res = await withdrawSolana({ recipient: recipientAddress, amount: amt });
        if (res && res.success && res.txHash) {
          setTxHash(res.txHash);
          setSolanaBalance(prev => prev !== null ? prev - amt : null);
          setTransactions(prev => [{
            id: 'tx_' + Math.random().toString(36).substring(2, 9),
            type: 'WITHDRAW' as const,
            amount: amt,
            currency: 'SOL',
            timestamp: Date.now(),
            status: 'COMPLETED',
            txHash: res.txHash,
            address: recipientAddress
          }, ...(prev || [])]);
          setWithdrawAmount('');
        } else {
          setErrorMsg(res.error || "Une erreur est survenue lors du retrait.");
        }
      } catch (err: any) {
        setErrorMsg(err.message || "Erreur blockchain.");
      } finally {
        setIsLoading(false);
      }
    }
  };

  const currentTxs = (Array.isArray(transactions) ? transactions : []).filter(tx =>
    tradingMode === 'REAL' ? tx.currency === 'SOL' : tx.currency === 'USD'
  );

  return (
    <div className="space-y-8 max-w-5xl mx-auto p-4 md:p-6 text-white" suppressHydrationWarning>
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 border-b border-white/5 pb-5">
        <div>
          <h1 className="text-3xl font-bold tracking-tight font-headline flex items-center gap-2">
            <ArrowUpRight className="h-8 w-8 text-rose-400" />
            Retirer des Fonds
          </h1>
          <p className="text-sm text-white/40 mt-1 font-body">Débitez vos fonds virtuels ou retirez vos gains Solana vers votre hot wallet.</p>
        </div>

        <div className="flex items-center bg-black/40 border border-white/10 p-1.5 rounded-xl gap-1 shrink-0">
          <Button
            variant="ghost"
            onClick={() => setTradingMode('DEMO')}
            className={cn("px-4 py-2 h-9 text-xs font-extrabold uppercase rounded-lg transition-all duration-200 font-headline flex items-center gap-2 border-none cursor-pointer",
              tradingMode === 'DEMO' ? "bg-amber-500/20 text-amber-300 border border-amber-500/40 shadow-sm font-black" : "text-white/40 hover:text-white hover:bg-white/5")}
          >
            <span className="h-2 w-2 rounded-full bg-amber-400" />
            Mode Démo
          </Button>
          <Button
            variant="ghost"
            onClick={() => setTradingMode('REAL')}
            className={cn("px-4 py-2 h-9 text-xs font-extrabold uppercase rounded-lg transition-all duration-200 font-headline flex items-center gap-2 border-none cursor-pointer",
              tradingMode === 'REAL' ? "bg-purple-600/25 text-purple-200 border border-purple-500/40 shadow-sm font-black" : "text-white/40 hover:text-white hover:bg-white/5")}
          >
            <span className="h-2 w-2 rounded-full bg-purple-400 animate-pulse" />
            Mode Réel (Solana)
          </Button>
        </div>
      </div>

      {/* Account Balance Overview Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <Card className="bg-[#14101a] border-white/10 rounded-2xl p-5 space-y-2 relative overflow-hidden shadow-xl">
          <span className="text-[10px] uppercase font-bold text-rose-400 font-headline block">Solde Actuel Retirable</span>
          <div className="text-2xl font-extrabold text-white font-body">
            {tradingMode === 'REAL' 
              ? `${solanaBalance !== null ? solanaBalance.toFixed(4) : '0.0000'} SOL` 
              : `${(balance || 0).toLocaleString('fr-FR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })} $ USD`
            }
          </div>
          <span className="text-[11px] text-rose-300/80 font-mono block font-semibold">
            {tradingMode === 'REAL' 
              ? formatSolToUsdAndHtg(solanaBalance).combinedLabel 
              : `≈ ${formatUsdToHtg(balance)}`
            }
          </span>
          <span className="text-[9px] text-white/30 font-body block mt-1">Disponible pour retrait immédiat ({tradingMode})</span>
        </Card>

        <Card className="bg-[#14101a] border-white/10 rounded-2xl p-5 space-y-2 relative overflow-hidden shadow-xl">
          <span className="text-[10px] uppercase font-bold text-amber-400 font-headline block">Mode de Compte</span>
          <div className="text-xl font-extrabold text-white font-body mt-1">
            {tradingMode === 'REAL' ? 'Solana Mainnet (Web3)' : 'Portefeuille Démo (USD)'}
          </div>
          <span className="text-[10px] text-emerald-400 font-mono block mt-0.5">
            ✓ Prêt pour l'opération
          </span>
          <span className="text-[9px] text-white/30 font-body block mt-1">Sélecteur de mode disponible en haut</span>
        </Card>

        <Card className="bg-[#14101a] border-white/10 rounded-2xl p-5 space-y-2 relative overflow-hidden shadow-xl flex flex-col justify-between">
          <div>
            <span className="text-[10px] uppercase font-bold text-cyan-400 font-headline block flex items-center gap-1">
              <RefreshCw className="h-3 w-3" /> Synchronisation
            </span>
            <div className="text-sm font-extrabold text-slate-200 font-body mt-1">
              {tradingMode === 'REAL' ? 'Blockchain Solana RPC' : 'Fonds virtuels simulés'}
            </div>
          </div>
          <Button
            onClick={() => {
              if (tradingMode === 'REAL') {
                getRealSolanaBalance().then(res => {
                  if (res && res.success && res.balance !== undefined) setSolanaBalance(res.balance);
                });
              }
            }}
            size="sm"
            className="h-8 bg-white/10 hover:bg-white/15 text-white border border-white/15 text-xs font-bold font-headline rounded-xl self-start mt-2 flex items-center gap-1.5 cursor-pointer"
          >
            <RefreshCw className="h-3.5 w-3.5" /> Actualiser Solde
          </Button>
        </Card>
      </div>

      {/* Interactive Coffre-Fort (Vault 10% SOL / USD) Card */}
      <ReserveVaultCard solanaBalance={solanaBalance} />

      <div className="grid grid-cols-1 md:grid-cols-12 gap-6">
        <div className="md:col-span-8">
          <WithdrawFormCard
            tradingMode={tradingMode}
            balance={balance}
            solanaBalance={solanaBalance}
            withdrawAmount={withdrawAmount}
            setWithdrawAmount={setWithdrawAmount}
            recipientAddress={recipientAddress}
            setRecipientAddress={setRecipientAddress}
            isLoading={isLoading}
            handleWithdraw={handleWithdraw}
            handlePercentClick={handlePercentClick}
            handleFillConnectedWeb3Address={handleFillConnectedWeb3Address}
            connectedWeb3Wallet={connectedWeb3Wallet}
            errorMsg={errorMsg}
            txHash={txHash}
          />
        </div>
      </div>

      <TransactionHistoryTable transactions={currentTxs} tradingMode={tradingMode} />
    </div>
  );
}

"use client";

import React from 'react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Button } from "@/components/ui/button";
import { BrainCircuit, TrendingUp, TrendingDown, Minus, RefreshCw } from "lucide-react";
import { cn } from "@/lib/utils";

interface AIAnalysisConsoleCardProps {
  pair: string;
  setPair: (val: string) => void;
  timeframe: string;
  setTimeframe: (val: string) => void;
  currencyPairs: { value: string; label: string }[];
  timeframes: { value: string; label: string }[];
  selectedIndicators: string[];
  setSelectedIndicators: React.Dispatch<React.SetStateAction<string[]>>;
  handleAnalysis: () => void;
  isChartReady: boolean;
  isLoading: boolean;
  error: string | null;
  debateLogs: { agent: string; msg: string; color: string }[];
  analysis: any;
}

export default function AIAnalysisConsoleCard({
  pair,
  setPair,
  timeframe,
  setTimeframe,
  currencyPairs,
  timeframes,
  selectedIndicators,
  setSelectedIndicators,
  handleAnalysis,
  isChartReady,
  isLoading,
  error,
  debateLogs,
  analysis
}: AIAnalysisConsoleCardProps) {
  const indicatorOptions = [
    { id: 'SMA', label: 'SMA (Simple)' },
    { id: 'EMA', label: 'EMA (Exp)' },
    { id: 'RSI', label: 'RSI' },
    { id: 'MACD', label: 'MACD' },
    { id: 'Bollinger Bands', label: 'Bandes Bollinger' },
    { id: 'Volume Profile (POC)', label: 'Profil de Volume (POC)' },
    { id: 'Candlestick Patterns', label: 'Modèles de Bougies' }
  ];

  return (
    <Card className="glass-panel border-white/5 shadow-xl flex flex-col justify-between overflow-hidden">
      <CardHeader className="pb-3">
        <CardTitle className="font-headline text-lg text-white flex items-center justify-between">
          <div className="flex items-center gap-2">
            <BrainCircuit className="h-5 w-5 text-[#c2ff0c]" />
            <span>Console Analyse IA</span>
          </div>
          <div className="flex items-center gap-1.5">
            <span className="text-[9px] font-mono font-extrabold px-2 py-0.5 rounded bg-emerald-500/20 text-emerald-300 border border-emerald-500/30">
              🔄 Auto-Apprentissage Actif
            </span>
            <span className="text-[9px] font-mono font-extrabold px-2 py-0.5 rounded bg-purple-600/20 text-purple-300 border border-purple-500/30">
              🎯 Sniper 14 Critères
            </span>
          </div>
        </CardTitle>
        <CardDescription className="text-white/40 text-xs font-body">
          Configurez la paire et le timeframe puis lancez l'analyse visuelle & algorithmique.
        </CardDescription>
      </CardHeader>

      <CardContent className="space-y-4 flex-1">
        <div className="space-y-1.5">
          <label className="text-xs font-bold text-white/60 uppercase font-headline">Paire de Devises</label>
          <Select value={pair} onValueChange={setPair}>
            <SelectTrigger className="h-11 bg-white/5 border-white/10 rounded-xl focus:ring-[#c2ff0c] text-white font-body">
              <SelectValue placeholder="Sélectionnez une paire..." />
            </SelectTrigger>
            <SelectContent className="bg-[#14101a] border-white/10 text-white font-body">
              {currencyPairs.map(p => (
                <SelectItem key={p.value} value={p.value}>{p.label}</SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        <div className="space-y-1.5">
          <label className="text-xs font-bold text-white/60 uppercase font-headline">Unité de Temps</label>
          <Select value={timeframe} onValueChange={setTimeframe}>
            <SelectTrigger className="h-11 bg-white/5 border-white/10 rounded-xl focus:ring-[#c2ff0c] text-white font-body">
              <SelectValue placeholder="Sélectionnez un timeframe..." />
            </SelectTrigger>
            <SelectContent className="bg-[#14101a] border-white/10 text-white font-body">
              {timeframes.map(t => (
                <SelectItem key={t.value} value={t.value}>{t.label}</SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        <div className="space-y-1.5">
          <label className="text-xs font-bold text-white/60 uppercase font-headline">Indicateurs Techniques</label>
          <div className="grid grid-cols-2 gap-2 bg-white/5 border border-white/10 rounded-xl p-2.5">
            {indicatorOptions.map((ind) => (
              <label key={ind.id} className="flex items-center gap-2 text-xs font-body text-white/80 cursor-pointer select-none py-1 hover:text-white transition-colors">
                <input 
                  type="checkbox"
                  checked={selectedIndicators.includes(ind.id)}
                  onChange={(e) => {
                    if (e.target.checked) {
                      setSelectedIndicators(prev => [...prev, ind.id]);
                    } else {
                      setSelectedIndicators(prev => prev.filter(x => x !== ind.id));
                    }
                  }}
                  className="accent-[#c2ff0c] rounded border-white/20 bg-white/5 h-3.5 w-3.5"
                />
                <span>{ind.label}</span>
              </label>
            ))}
          </div>
        </div>

        <Button 
          onClick={handleAnalysis} 
          disabled={!isChartReady || isLoading} 
          className={cn(
            "w-full h-11 rounded-xl text-black font-semibold transition-all duration-300 font-headline",
            isLoading ? "bg-white/20 text-white" : "bg-[#c2ff0c] hover:bg-[#c2ff0c]/90 hover:shadow-[0_0_15px_rgba(194,255,12,0.3)]"
          )}
        >
          {isLoading ? (
            <span className="flex items-center gap-2 justify-center">
              <RefreshCw className="h-4 w-4 animate-spin" />
              Analyse en cours...
            </span>
          ) : (
            isChartReady ? 'Analyser le Graphique' : 'Chargement du graphique...'
          )}
        </Button>

        <div className="h-[1px] bg-white/5 my-4" />

        <div className="flex-1 flex flex-col justify-center min-h-[160px] p-3.5 rounded-xl bg-white/5 border border-white/5 space-y-3">
          {error && <p className="text-red-400 text-sm text-center font-body">{error}</p>}

          {debateLogs.length > 0 && (
            <div className="border border-white/5 bg-[#0e0a12]/70 rounded-xl p-3 font-mono text-[9px] space-y-1.5 max-h-[140px] overflow-y-auto">
              <div className="text-[8px] uppercase tracking-wider font-bold text-white/30 font-headline mb-1 flex items-center justify-between">
                <span>Syndicate Consensus Channel</span>
                <span className="h-1.5 w-1.5 rounded-full bg-cyan-400 animate-pulse" />
              </div>
              {debateLogs.map((log, index) => (
                <div key={index} className="flex items-start gap-1.5 leading-normal animate-in fade-in duration-200">
                  <span className={cn("font-bold shrink-0", log.color)}>[{log.agent}] :</span>
                  <span className="text-white/70">{log.msg}</span>
                </div>
              ))}
            </div>
          )}

          {analysis && !isLoading && (
            <div className="space-y-3.5 pt-1.5 border-t border-white/5">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2.5">
                  <div className={cn(
                    "p-2 rounded-lg shrink-0",
                    analysis.signal === 'ACHAT' ? "bg-green-500/10 text-green-400" :
                    analysis.signal === 'VENTE' ? "bg-red-500/10 text-red-400" : "bg-white/10 text-white/60"
                  )}>
                    {analysis.signal === 'ACHAT' ? <TrendingUp className="h-5 w-5" /> :
                     analysis.signal === 'VENTE' ? <TrendingDown className="h-5 w-5" /> : <Minus className="h-5 w-5" />}
                  </div>
                  <div>
                    <p className="text-[10px] text-white/40 uppercase font-bold leading-none font-headline">Consensus Final</p>
                    <p className={cn(
                      "text-lg font-black leading-none mt-1.5 font-headline",
                      analysis.signal === 'ACHAT' ? "text-green-400" :
                      analysis.signal === 'VENTE' ? "text-red-400" : "text-white/60"
                    )}>{analysis.signal}</p>
                  </div>
                </div>
                <div className="text-right">
                  <span className="text-[10px] text-white/40 uppercase font-bold leading-none font-headline">Tendance</span>
                  <p className="text-xs font-bold text-white leading-none mt-1.5">{analysis.trend}</p>
                </div>
              </div>
              <div className="space-y-1.5">
                <span className="text-[10px] text-white/40 uppercase font-bold font-headline">Justification du Consensus</span>
                <p className="text-xs text-white/80 leading-relaxed font-body">
                  {analysis.justification}
                </p>
              </div>
            </div>
          )}

          {!analysis && !isLoading && (
            <div className="text-center py-6 text-white/30 flex flex-col items-center justify-center">
              <BrainCircuit className="h-8 w-8 mb-2 opacity-50"/>
              <p className="text-xs font-body">Les résultats de l'analyse IA s'afficheront ici après avoir cliqué sur le bouton ci-dessus.</p>
            </div>
          )}
        </div>
      </CardContent>
    </Card>
  );
}

"use client";

import React from 'react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { History } from "lucide-react";
