"use client";

import React, { useState, useRef } from 'react';
import { 
  TrendingUp, 
  TrendingDown, 
  Activity, 
  Zap 
} from 'lucide-react';
import { cn, formatSolToUsdAndHtg, formatUsdToHtg, getRealMarketBasePrice } from '@/lib/utils';
import { useAppState } from '@/context/AppContext';
import { executeRealPumpTrade, fetchLatestPumpCoins, fetchRealPumpCoins } from '@/services/pumpFunService';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { 
  Select, 
  SelectTrigger, 
  SelectValue, 
  SelectContent, 
  SelectItem 
} from '@/components/ui/select';
import { Slider } from '@/components/ui/slider';

import PositionRiskCalculator from '@/components/trading/PositionRiskCalculator';
import { currencyPairs as allCurrencyPairs } from '@/hooks/useTradingSimulation';
const currencyPairs = allCurrencyPairs.filter(c => c.value !== 'ALL');

interface ManualOrderFormProps {
  livePrices: { [key: string]: number };
  priceDirections: { [key: string]: 'up' | 'down' | 'flat' };
  solanaBalance: number | null;
  solanaPubKey: string;
  isSolanaWalletActive: boolean;
  addBotLog: (botId: string, botName: string, message: string, type: 'info' | 'trade' | 'error') => void;
  selectedPair: string;
  setSelectedPair: (pair: string) => void;
}

export default function ManualOrderForm({
  livePrices,
  priceDirections,
  solanaBalance,
  solanaPubKey,
  isSolanaWalletActive,
  addBotLog,
  selectedPair,
  setSelectedPair
}: ManualOrderFormProps) {
  const { tradingMode, balance, setBalance, reserveVault, setActivePositions, activePositions } = useAppState();

  // Local Form States
  const [orderType, setOrderType] = useState<'BUY' | 'SELL'>('BUY');
  const [orderAmount, setOrderAmount] = useState<number>(500);
  const [leverage, setLeverage] = useState<number>(10);
  const [stopLoss, setStopLoss] = useState<string>('');
  const [takeProfit, setTakeProfit] = useState<string>('');
  const [trendingCoins, setTrendingCoins] = useState<any[]>([]);
  const [trendingCoinsError, setTrendingCoinsError] = useState<string>('');

  const isSubmittingOrderRef = useRef(false);

  // Fetch live trending coins from Pump.fun (real mints only in REAL mode)
  React.useEffect(() => {
    if (tradingMode !== 'REAL') return;
    const loadCoins = async () => {
      try {
        setTrendingCoinsError('');
        const coins = await fetchRealPumpCoins();
        if (coins && coins.length > 0) {
          setTrendingCoins(coins.slice(0, 15));
        }
      } catch (e: any) {
        setTrendingCoinsError(e.message || 'API Pump.fun inaccessible.');
        setTrendingCoins([]);
      }
    };
    loadCoins();
    const interval = setInterval(loadCoins, 10000);
    return () => clearInterval(interval);
  }, [tradingMode]);

  const handlePlaceOrder = (e: React.FormEvent) => {
    e.preventDefault();
    if (isSubmittingOrderRef.current) return;
    isSubmittingOrderRef.current = true;

    setTimeout(() => {
      isSubmittingOrderRef.current = false;
    }, 500);

    const currentPrice = (livePrices[selectedPair] && livePrices[selectedPair] > 0) 
      ? livePrices[selectedPair] 
      : getRealMarketBasePrice(selectedPair);

    if (tradingMode === 'REAL') {
      if (selectedPair.startsWith('SOL:')) {
        const parts = selectedPair.split(':');
        const mintAddress = parts[1];
        if (!mintAddress || mintAddress.startsWith('ukhh')) {
          alert("Adresse de contrat Solana invalide.");
          return;
        }
        if (orderAmount <= 0) {
          alert("Le montant doit être supérieur à 0.");
          return;
        }
        if (solanaBalance === null || orderAmount > solanaBalance) {
          alert(`Solde SOL insuffisant. Requis: ${orderAmount} SOL, Disponible: ${solanaBalance?.toFixed(3)} SOL`);
          return;
        }

        const tokenSymbol = parts[2] || 'TOKEN';
        addBotLog("manual", "Manuel", `Envoi d'un ordre d'achat réel de ${orderAmount} SOL pour $${tokenSymbol}...`, 'info');

        executeRealPumpTrade({
          action: 'buy',
          mint: mintAddress,
          amount: orderAmount,
          denominatedInSol: true,
          slippage: 15,
          priorityFee: 0.005
        }).then((res) => {
          if (res && res.success && res.txHash) {
            addBotLog("manual", "Manuel", `[ACHAT MANUEL RÉEL RÉUSSI] Transaction confirmée ! Hash: ${res.txHash.slice(0, 16)}...`, 'trade');

            const newRealPos = {
              id: 'pos_' + Math.random().toString(36).substring(2, 9),
              pair: selectedPair,
              type: 'BUY',
              entryPrice: currentPrice,
              currentPrice: currentPrice,
              amount: orderAmount,
              leverage: 1,
              timestamp: Date.now(),
              txHash: res.txHash,
              mode: 'REAL' as const
            };

            setActivePositions(prev => [...prev, newRealPos]);
            window.dispatchEvent(new Event('web3_wallet_updated'));
          } else {
            addBotLog("manual", "Manuel", `[ÉCHEC ACHAT MANUEL RÉEL] ${res.error || 'Erreur réseau/RPC Solana.'}`, 'error');
          }
        });
        return;
      }

      // Ordres manuels multi-actifs (Crypto, Forex, Matières Premières) en Mode Réel sur Marge Synthétique
      if (orderAmount <= 0) {
        alert("Le montant doit être supérieur à 0.");
        return;
      }
      if (solanaBalance !== null && orderAmount > solanaBalance) {
        alert(`Solde de marge SOL insuffisant. Requis: ${orderAmount} SOL, Disponible: ${solanaBalance.toFixed(3)} SOL.`);
        return;
      }
    }

    if (orderAmount <= 0) {
      alert("Le montant doit être supérieur à 0.");
      return;
    }

    const marginRequired = orderAmount;
    const allocatableBalance = Math.max(0, balance - (reserveVault || 0));
    if (marginRequired > allocatableBalance) {
      alert(`Capital allocable insuffisant (hors Coffre-Fort 10%). Marge requise: $${marginRequired}, Capital allocable: $${allocatableBalance.toFixed(2)}. Coffre-Fort protégé: $${(Number(reserveVault) || 0).toFixed(2)}`);
      return;
    }

    const sl = stopLoss ? parseFloat(stopLoss) : undefined;
    const tp = takeProfit ? parseFloat(takeProfit) : undefined;

    const newPos = {
      id: 'pos_' + Math.random().toString(36).substring(2, 9),
      pair: selectedPair,
      type: orderType,
      entryPrice: currentPrice,
      currentPrice: currentPrice,
      amount: orderAmount,
      leverage: leverage,
      sl,
      tp,
      timestamp: Date.now(),
      mode: tradingMode
    };

    setActivePositions(prev => {
      if (prev.some(x => x.id === newPos.id)) return prev;
      return [...prev, newPos];
    });
    if (tradingMode === 'DEMO') {
      setBalance(bal => bal - marginRequired);
    } else {
      if (typeof window !== 'undefined') {
        window.dispatchEvent(new Event('web3_wallet_updated'));
      }
    }

    setStopLoss('');
    setTakeProfit('');
  };

  const activePairPrice = livePrices[selectedPair] || 0;

  return (
    <Card className="bg-[#150f21] border-white/15 rounded-2xl p-6 space-y-5 shadow-2xl">
      <CardHeader className="p-0 flex flex-row justify-between items-center space-y-0 border-b border-white/10 pb-3">
        <CardTitle className="text-base font-extrabold uppercase tracking-wider text-white font-headline">
          Passer un Ordre
        </CardTitle>
        <div className="flex items-center gap-2 text-xs font-extrabold text-emerald-400 font-body">
          <Activity className="h-4 w-4 text-emerald-400 animate-pulse" />
          Flux Direct Live
        </div>
      </CardHeader>

      <div className="mb-4">
        <PositionRiskCalculator solanaBalance={solanaBalance} />
      </div>

      <form onSubmit={handlePlaceOrder} className="space-y-4">
        {tradingMode === 'DEMO' ? (
          <>
            {/* Pair Selection */}
            <div className="space-y-2">
              <label className="text-xs font-extrabold text-slate-200 uppercase tracking-wider font-headline">Paire de Devises (Démo)</label>
              <Select value={selectedPair} onValueChange={setSelectedPair}>
                <SelectTrigger className="w-full h-11 bg-black/40 border border-white/15 rounded-xl px-4 text-sm font-bold focus:ring-[#c2ff0c] text-white font-body">
                  <SelectValue placeholder="Choisir une paire" />
                </SelectTrigger>
                <SelectContent className="bg-[#150f21] border-white/15 text-white">
                  {currencyPairs.map(c => (
                    <SelectItem key={c.value} value={c.value} className="focus:bg-white/10 focus:text-white cursor-pointer font-semibold text-xs">
                      {c.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            {/* Price Display */}
            <div className="bg-black/40 border border-white/15 rounded-xl p-4 flex justify-between items-center">
              <span className="text-xs font-extrabold uppercase text-slate-200 font-body">Prix Actuel :</span>
              <div className="flex items-center gap-2">
                <span className={cn(
                  "text-2xl font-black font-mono transition-colors duration-300",
                  priceDirections[selectedPair] === 'up' ? 'text-emerald-400' :
                  priceDirections[selectedPair] === 'down' ? 'text-rose-400' : 'text-white'
                )}>
                  {activePairPrice ? activePairPrice.toFixed(5) : 'Chargement...'}
                </span>
                {priceDirections[selectedPair] === 'up' && <TrendingUp className="h-5 w-5 text-emerald-400" />}
                {priceDirections[selectedPair] === 'down' && <TrendingDown className="h-5 w-5 text-rose-400" />}
              </div>
            </div>

            {/* Order Type Toggle */}
            <div className="grid grid-cols-2 gap-2.5">
              <Button
                type="button"
                variant="ghost"
                onClick={() => setOrderType('BUY')}
                className={cn(
                  "h-11 rounded-xl font-bold text-xs transition-all duration-300 font-headline uppercase",
                  orderType === 'BUY' 
                    ? "bg-emerald-500/20 text-emerald-400 border border-emerald-500/30 shadow-[0_0_12px_rgba(16,185,129,0.2)] hover:bg-emerald-500/30 hover:text-emerald-300" 
                    : "bg-white/5 text-white/40 border border-white/5 hover:text-white hover:bg-white/10"
                )}
              >
                ACHAT (LONG)
              </Button>
              <Button
                type="button"
                variant="ghost"
                onClick={() => setOrderType('SELL')}
                className={cn(
                  "h-11 rounded-xl font-bold text-xs transition-all duration-300 font-headline uppercase",
                  orderType === 'SELL' 
                    ? "bg-rose-500/20 text-rose-400 border border-rose-500/30 shadow-[0_0_12px_rgba(244,63,94,0.2)] hover:bg-rose-500/30 hover:text-rose-300" 
                    : "bg-white/5 text-white/40 border border-white/5 hover:text-white hover:bg-white/10"
                )}
              >
                VENTE (SHORT)
              </Button>
            </div>

            {/* Amount input */}
            <div className="space-y-1.5">
              <div className="flex justify-between items-center">
                <label className="text-[10px] font-bold text-white/40 uppercase font-headline">Montant (Marge en USD)</label>
                <span className="text-[10px] text-white/40 font-body">Max: {balance.toFixed(0)} $</span>
              </div>
              <div className="relative">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-white/40 text-sm">$</span>
                <Input
                  type="number"
                  value={orderAmount || ""}
                  onChange={(e) => setOrderAmount(Math.max(0, parseFloat(e.target.value) || 0))}
                  className="w-full h-11 bg-white/5 border border-white/10 rounded-xl pl-8 pr-3 text-sm focus:ring-[#c2ff0c] text-white font-body focus:outline-none"
                />
              </div>
            </div>

            {/* Leverage Slider */}
            <div className="space-y-1.5 bg-white/5 border border-white/10 rounded-xl p-3.5">
              <div className="flex justify-between items-center">
                <label className="text-[10px] font-bold text-white/40 uppercase font-headline">Effet de Levier</label>
                <span className="text-xs font-bold text-[#c2ff0c] font-body">{leverage}x</span>
              </div>
              <Slider
                min={1}
                max={100}
                step={1}
                value={[leverage]}
                onValueChange={(val) => setLeverage(val[0])}
                className="w-full mt-2"
              />
              <div className="flex justify-between text-[8px] text-white/20 font-body px-0.5 mt-1">
                <span>1x</span>
                <span>25x</span>
                <span>50x</span>
                <span>75x</span>
                <span>100x</span>
              </div>
            </div>

            {/* SL / TP inputs */}
            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-1.5">
                <label className="text-[10px] font-bold text-white/40 uppercase font-headline">Stop Loss (Prix)</label>
                <Input
                  type="number"
                  step="0.00001"
                  value={stopLoss}
                  placeholder={activePairPrice ? (orderType === 'BUY' ? (activePairPrice * 0.985).toFixed(5) : (activePairPrice * 1.015).toFixed(5)) : 'Facultatif'}
                  onChange={(e) => setStopLoss(e.target.value)}
                  className="w-full h-11 bg-white/5 border border-white/10 rounded-xl px-3 text-xs focus:ring-[#c2ff0c] text-white font-body focus:outline-none"
                />
              </div>
              <div className="space-y-1.5">
                <label className="text-[10px] font-bold text-white/40 uppercase font-headline">Take Profit (Prix)</label>
                <Input
                  type="number"
                  step="0.00001"
                  value={takeProfit}
                  placeholder={activePairPrice ? (orderType === 'BUY' ? (activePairPrice * 1.03).toFixed(5) : (activePairPrice * 0.97).toFixed(5)) : 'Facultatif'}
                  onChange={(e) => setTakeProfit(e.target.value)}
                  className="w-full h-11 bg-white/5 border border-white/10 rounded-xl px-3 text-xs focus:ring-[#c2ff0c] text-white font-body focus:outline-none"
                />
              </div>
            </div>

            {/* Place Order Button */}
            <Button
              type="submit"
              className={cn(
                "w-full h-12 rounded-xl text-black font-semibold text-xs transition-all duration-300 font-headline uppercase tracking-wider mt-2 border-none",
                orderType === 'BUY' 
                  ? "bg-emerald-400 hover:bg-emerald-500 hover:shadow-[0_0_15px_rgba(52,211,153,0.3)] text-emerald-950"
                  : "bg-rose-400 hover:bg-rose-500 hover:shadow-[0_0_15px_rgba(251,113,133,0.3)] text-rose-955"
              )}
            >
              Ouvrir la Position {orderType === 'BUY' ? 'LONG' : 'SHORT'}
            </Button>
          </>
        ) : (
          <>
            {/* Solana Custom CA Input */}
            <div className="space-y-3 bg-purple-950/10 border border-purple-500/15 p-4 rounded-xl">
              <div className="space-y-1.5">
                <div className="flex justify-between items-center">
                  <label className="text-[10px] font-bold text-purple-300 uppercase font-headline">Sélection Jeton Solana en Temps Réel</label>
                  <span className="text-[9px] text-[#c2ff0c] font-mono animate-pulse">● Live Stream On-Chain</span>
                </div>
                <Select
                  value={selectedPair}
                  onValueChange={(val) => {
                    setSelectedPair(val);
                  }}
                >
                  <SelectTrigger className="w-full h-11 bg-white/5 border border-white/10 rounded-xl px-3 text-sm focus:ring-[#c2ff0c] text-white font-body">
                    <SelectValue placeholder="Sélectionner un jeton en temps réel..." />
                  </SelectTrigger>
                  <SelectContent className="bg-[#14101a] border-white/10 text-white max-h-64">
                    {trendingCoinsError ? (
                      <div className="px-3 py-4 text-center">
                        <p className="text-xs text-rose-400 font-bold">⚠️ API Pump.fun indisponible</p>
                        <p className="text-[10px] text-white/40 mt-1">{trendingCoinsError}</p>
                        <p className="text-[10px] text-white/40 mt-1">Saisissez le Mint Address manuellement ci-dessous.</p>
                      </div>
                    ) : trendingCoins.length > 0 ? (
                      trendingCoins.map(coin => (
                        <SelectItem key={coin.mint} value={`SOL:${coin.mint}:${coin.symbol}`} className="focus:bg-white/10 focus:text-white cursor-pointer text-xs">
                          ${coin.symbol} — {coin.name} ({Math.max(0, Math.min(100, (((coin.virtual_sol_reserves / 1e9) - 30) / 55) * 100)).toFixed(0)}% Curve)
                        </SelectItem>
                      ))
                    ) : (
                      <div className="px-3 py-4 text-center">
                        <div className="h-4 w-4 animate-spin rounded-full border-2 border-t-transparent border-purple-400 mx-auto mb-2" />
                        <p className="text-[10px] text-white/40">Chargement des jetons Pump.fun en live...</p>
                      </div>
                    )}
                    <SelectItem value="SOL:custom_mint:Token" className="focus:bg-white/10 focus:text-white cursor-pointer text-xs font-bold text-[#c2ff0c]">
                      ➕ Saisir un autre Mint Address (CA)...
                    </SelectItem>
                  </SelectContent>
                </Select>
              </div>

              {(!selectedPair.startsWith('SOL:') || selectedPair.split(':')[1].startsWith('ukhh') || selectedPair.includes('custom_mint')) && (
                <div className="space-y-1.5 animate-in fade-in duration-200">
                  <label className="text-[10px] font-bold text-purple-300 uppercase font-headline">Adresse du Contrat du Jeton (Mint CA)</label>
                  <Input
                    type="text"
                    placeholder="Collez le Mint Address (ex: FNt55...)"
                    value={selectedPair.startsWith('SOL:') && !selectedPair.split(':')[1].startsWith('ukhh') && !selectedPair.includes('custom_mint') ? selectedPair.split(':')[1] : ''}
                    onChange={(e) => {
                      const ca = e.target.value.trim();
                      if (ca) {
                        setSelectedPair(`SOL:${ca}:Token`);
                      }
                    }}
                    className="w-full h-11 bg-white/5 border border-white/10 rounded-xl px-3 text-xs focus:ring-[#c2ff0c] text-white font-mono focus:outline-none"
                  />
                </div>
              )}
            </div>

            {/* Amount in SOL */}
            <div className="space-y-1.5">
              <div className="flex justify-between items-center">
                <label className="text-[10px] font-bold text-purple-300 uppercase font-headline">Montant à Acheter (SOL)</label>
                <span className="text-[10px] text-[#c2ff0c] font-mono font-semibold">
                  Disponible : {solanaBalance !== null ? `${solanaBalance.toFixed(3)} SOL (${formatSolToUsdAndHtg(solanaBalance).combinedLabel})` : '0.00 SOL'}
                </span>
              </div>
              <div className="relative">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-purple-300 text-xs font-mono">SOL</span>
                <Input
                  type="number"
                  step="0.01"
                  min="0.001"
                  value={orderAmount || ""}
                  onChange={(e) => setOrderAmount(Math.max(0.001, parseFloat(e.target.value) || 0))}
                  className="w-full h-11 bg-white/5 border border-white/10 rounded-xl pl-12 pr-3 text-sm focus:ring-[#c2ff0c] text-white font-body focus:outline-none"
                />
              </div>
              {orderAmount > 0 && (
                <span className="text-[10px] text-purple-300/80 font-mono block pl-1">
                  {formatSolToUsdAndHtg(orderAmount).combinedLabel}
                </span>
              )}
            </div>

            {/* Disclaimer & Execution button */}
            <div className="p-3 bg-purple-950/10 border border-purple-500/10 rounded-xl text-[9px] text-purple-300/70 leading-normal font-body">
              ⚡ Les ordres manuels en Mode Réel sont acheminés en direct via votre nœud Chainstack et s'exécutent sur la blockchain Solana. Le levier est forcé à 1x (Spot).
            </div>

            <Button
              type="submit"
              disabled={!isSolanaWalletActive}
              className="w-full h-12 bg-purple-600 hover:bg-purple-500 disabled:bg-white/10 disabled:text-white/30 text-white font-semibold text-xs rounded-xl transition-all duration-300 font-headline uppercase tracking-wider mt-2 hover:shadow-[0_0_20px_rgba(147,51,234,0.4)] border border-purple-500/40"
            >
              Exécuter l'Achat Réel sur Solana
            </Button>
          </>
        )}
      </form>
    </Card>
  );
}

"use client";

import React, { useState } from 'react';
import { 
  TrendingUp, 
  TrendingDown, 
  Zap, 
  Eye, 
  BarChart2, 
  Globe 
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { 
  Select, 
  SelectTrigger, 
  SelectValue, 
  SelectContent, 
  SelectItem 
} from '@/components/ui/select';
import { currencyPairs, timeframes } from '@/hooks/useTradingSimulation';
import TradingViewWidget from '@/components/trading/TradingViewWidget';

interface MarketRadarAndChartProps {
  selectedPair: string;
  setSelectedPair: (pair: string) => void;
  livePrices: { [key: string]: number };
  priceDirections: { [key: string]: 'up' | 'down' | 'flat' };
  botLogs: Array<{
    id: string;
    botId: string;
    botName: string;
    message: string;
    type: 'info' | 'trade' | 'error';
    timestamp: number;
  }>;
  bots: Array<{
    id: string;
    pair: string;
    strategy: string;
    status: string;
    capital: number;
    netProfit?: number;
  }>;
}

export default function MarketRadarAndChart({
  selectedPair,
  setSelectedPair,
  livePrices,
  priceDirections,
  botLogs,
  bots
}: MarketRadarAndChartProps) {
  const [activeTab, setActiveTab] = useState<'chart' | 'radar' | 'ai'>('chart');
  const [chartTimeframe, setChartTimeframe] = useState<string>('15');
  const [selectedIndicators, setSelectedIndicators] = useState<string[]>(['RSI', 'EMA', 'Bollinger Bands']);

  const actualPair = selectedPair === 'ALL' || selectedPair === 'SOLANA' ? 'FX:EURUSD' : selectedPair;
  const currentPrice = livePrices[actualPair] || 0;

  const toggleIndicator = (ind: string) => {
    setSelectedIndicators(prev => 
      prev.includes(ind) ? prev.filter(i => i !== ind) : [...prev, ind]
    );
  };

  // Compute live multi-asset metrics for radar matrix
  const radarList = currencyPairs.filter(cp => cp.value !== 'ALL').map(cp => {
    const price = livePrices[cp.value] || 0;
    const dir = priceDirections[cp.value] || 'flat';

    const change = price > 0 ? (dir === 'up' ? 0.42 : dir === 'down' ? -0.38 : 0) : 0;
    const rsi = price > 0 ? (dir === 'up' ? 62 : dir === 'down' ? 38 : 50) : 50;
    const rsiStatus = rsi < 35 ? 'SURVENDU (Achat)' : rsi > 65 ? 'SURACHETÉ (Vente)' : 'NEUTRE';

    const safeBots = Array.isArray(bots) ? bots : [];
    const botActiveOnPair = safeBots.some(b => b && b.status === 'RUNNING' && (b.pair === 'ALL' || b.pair === cp.value));

    return {
      ...cp,
      price,
      dir,
      change,
      rsi,
      rsiStatus,
      botActive: botActiveOnPair
    };

  });

  return (
    <Card className="bg-[#150f21] border border-white/15 rounded-2xl p-5 md:p-6 shadow-2xl flex flex-col h-[660px] overflow-hidden">
      {/* Header Bar */}
      <CardHeader className="p-0 pb-4 border-b border-white/10 shrink-0">
        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-3">
          {/* Main Title & Active Pair Display */}
          <div className="flex items-center gap-3">
            <div className="p-2.5 bg-[#c2ff0c]/15 border border-[#c2ff0c]/30 rounded-xl text-[#c2ff0c]">
              <Globe className="h-5 w-5 animate-spin-slow" />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <CardTitle className="text-base font-extrabold uppercase tracking-wider text-white font-headline">
                  Centre d'Analyse Multi-Actifs
                </CardTitle>
                <Badge className="bg-[#c2ff0c]/20 text-[#c2ff0c] text-xs font-headline uppercase font-bold border-none">
                  Live Stream 24/7
                </Badge>
              </div>
              <p className="text-xs text-slate-300 font-medium font-body mt-0.5">
                Scanneur de marché en temps réel & graphiques multi-indicateurs pour bots algorithmiques.
              </p>
            </div>
          </div>

          {/* Sub-tab Navigation */}
          <div className="flex bg-black/40 border border-white/15 p-1.5 rounded-xl gap-1 shrink-0">
            <Button
              variant="ghost"
              onClick={() => setActiveTab('chart')}
              className={cn(
                "px-3.5 py-2 h-auto text-xs font-extrabold uppercase rounded-lg transition-all font-headline flex items-center gap-1.5 border-none",
                activeTab === 'chart' 
                  ? "bg-white/20 text-white shadow-md font-black" 
                  : "text-slate-300 hover:text-white hover:bg-white/10"
              )}
            >
              <BarChart2 className="h-3.5 w-3.5 text-[#c2ff0c]" />
              Graphique Pro
            </Button>
            <Button
              variant="ghost"
              onClick={() => setActiveTab('radar')}
              className={cn(
                "px-3.5 py-2 h-auto text-xs font-extrabold uppercase rounded-lg transition-all font-headline flex items-center gap-1.5 border-none",
                activeTab === 'radar' 
                  ? "bg-white/20 text-white shadow-md font-black" 
                  : "text-slate-300 hover:text-white hover:bg-white/10"
              )}
            >
              <Eye className="h-3.5 w-3.5 text-cyan-400" />
              Radar Actifs ({radarList.length})
            </Button>
            <Button
              variant="ghost"
              onClick={() => setActiveTab('ai')}
              className={cn(
                "px-3.5 py-2 h-auto text-xs font-extrabold uppercase rounded-lg transition-all font-headline flex items-center gap-1.5 border-none",
                activeTab === 'ai' 
                  ? "bg-white/20 text-white shadow-md font-black" 
                  : "text-slate-300 hover:text-white hover:bg-white/10"
              )}
            >
              <Zap className="h-3.5 w-3.5 text-amber-400" />
              Signaux IA
            </Button>
          </div>
        </div>
      </CardHeader>

      {/* Main Content Body */}
      <CardContent className="p-0 pt-4 flex-1 flex flex-col min-h-0 overflow-hidden">
        {/* TAB 1: CHART PRO */}
        {activeTab === 'chart' && (
          <div className="flex flex-col h-full space-y-3">
            {/* Chart Control Bar */}
            <div className="flex flex-wrap items-center justify-between gap-2 bg-white/5 border border-white/5 p-2 rounded-xl text-xs">
              {/* Pair Selector */}
              <div className="flex items-center gap-2">
                <span className="text-[10px] text-white/40 uppercase font-headline font-bold">Actif :</span>
                <Select value={actualPair} onValueChange={setSelectedPair}>
                  <SelectTrigger className="h-8 bg-white/5 border-white/10 text-xs text-white font-body rounded-lg min-w-[130px]">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent className="bg-[#14101a] border-white/10 text-white">
                    {currencyPairs.filter(c => c.value !== 'ALL').map(cp => (
                      <SelectItem key={cp.value} value={cp.value} className="focus:bg-white/10 cursor-pointer text-xs">
                        {cp.label}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>

                {/* Price Display */}
                <div className="flex items-center gap-1.5 ml-2 font-mono">
                  <span className={cn(
                    "text-sm font-bold",
                    priceDirections[actualPair] === 'up' ? 'text-emerald-400' :
                    priceDirections[actualPair] === 'down' ? 'text-rose-400' : 'text-white'
                  )}>
                    {currentPrice ? currentPrice.toFixed(currentPrice > 100 ? 2 : (currentPrice < 10 ? 4 : 2)) : '—'}
                  </span>
                  {priceDirections[actualPair] === 'up' && <TrendingUp className="h-3.5 w-3.5 text-emerald-400" />}
                  {priceDirections[actualPair] === 'down' && <TrendingDown className="h-3.5 w-3.5 text-rose-400" />}
                </div>
              </div>

              {/* Timeframe Buttons */}
              <div className="flex items-center gap-1">
                <span className="text-[10px] text-white/40 uppercase font-headline font-bold mr-1">Tf :</span>
                {timeframes.map(tf => (
                  <Button
                    key={tf.value}
                    variant="ghost"
                    size="sm"
                    onClick={() => setChartTimeframe(tf.value)}
                    className={cn(
                      "h-7 px-2 text-[10px] font-bold rounded-md font-body border-none",
                      chartTimeframe === tf.value
                        ? "bg-[#c2ff0c] text-black font-extrabold"
                        : "bg-white/5 text-white/40 hover:text-white hover:bg-white/10"
                    )}
                  >
                    {tf.value === '1' ? '1m' : tf.value === '5' ? '5m' : tf.value === '15' ? '15m' : tf.value === '60' ? '1h' : '4h'}
                  </Button>
                ))}
              </div>

              {/* Indicator Toggles */}
              <div className="flex items-center gap-1">
                {['RSI', 'EMA', 'Bollinger Bands', 'MACD'].map(ind => (
                  <Button
                    key={ind}
                    variant="ghost"
                    size="sm"
                    onClick={() => toggleIndicator(ind)}
                    className={cn(
                      "h-7 px-2 text-[9px] font-bold rounded-md font-headline uppercase border",
                      selectedIndicators.includes(ind)
                        ? "bg-violet-500/20 text-violet-300 border-violet-500/40"
                        : "bg-white/5 text-white/30 border-white/5 hover:text-white"
                    )}
                  >
                    {ind}
                  </Button>
                ))}
              </div>
            </div>

            {/* TradingView Widget Frame */}
            <div className="flex-1 bg-black/40 border border-white/5 rounded-xl overflow-hidden relative min-h-[360px]">
              <TradingViewWidget
                symbol={actualPair}
                interval={chartTimeframe}
                indicators={selectedIndicators}
              />
            </div>
          </div>
        )}

        {/* TAB 2: MULTI-ASSET RADAR MATRIX */}
        {activeTab === 'radar' && (
          <div className="flex flex-col h-full space-y-3 min-h-0">
            <div className="flex justify-between items-center bg-white/5 border border-white/5 p-2.5 rounded-xl">
              <span className="text-xs text-white/70 font-headline font-bold uppercase flex items-center gap-1.5">
                <Globe className="h-3.5 w-3.5 text-cyan-400" />
                Matrice Radar Multi-Paires & Détection Opportunités
              </span>
              <Badge className="bg-cyan-500/15 text-cyan-300 text-[9px] font-bold border-none uppercase font-headline">
                {radarList.length} Actifs Scannés Continu
              </Badge>
            </div>

            <div className="flex-1 overflow-y-auto pr-1 space-y-2 max-h-[480px]">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-2.5">
                {radarList.map((item) => (
                  <div
                    key={item.value}
                    onClick={() => {
                      setSelectedPair(item.value);
                      setActiveTab('chart');
                    }}
                    className={cn(
                      "bg-white/5 border rounded-xl p-3 cursor-pointer transition-all duration-200 hover:scale-[1.01] flex justify-between items-center group",
                      selectedPair === item.value 
                        ? "border-[#c2ff0c]/50 bg-[#c2ff0c]/5 shadow-[0_0_15px_rgba(194,255,12,0.1)]" 
                        : "border-white/5 hover:border-white/20 hover:bg-white/10"
                    )}
                  >
                    <div className="space-y-1">
                      <div className="flex items-center gap-2">
                        <span className="font-bold text-sm text-white font-headline">{item.label}</span>
                        {item.botActive && (
                          <Badge className="bg-[#c2ff0c]/20 text-[#c2ff0c] text-[8px] font-bold border-none uppercase px-1.5">
                            Bot Actif
