            </span>
            <span className="text-[9px] text-rose-300/80 font-mono block mt-0.5">
              Risque max: -{formatSmartPnl(position.amount * ((position.sl && position.sl < 100 ? position.sl : 3) / 100), isSol)} {isSol ? 'SOL' : '$'}
