interface TradingBotsManagerProps {
  solanaBalance: number | null;
  setSolanaBalance: React.Dispatch<React.SetStateAction<number | null>>;
  isSolanaWalletActive: boolean;
  addBotLog: (botId: string, botName: string, message: string, type: 'info' | 'trade' | 'error') => void;
  handleToggleBot: (botId: string) => void;
  handleDeleteBot: (botId: string) => void;
  livePrices: { [key: string]: number };
}

export default function TradingBotsManager({
  solanaBalance,
  setSolanaBalance,
  isSolanaWalletActive,
  addBotLog,
  handleToggleBot,
  handleDeleteBot,
  livePrices
}: TradingBotsManagerProps) {
  const { 
    tradingMode, 
    balance, 
    setBalance, 
    reserveVault,
    setReserveVault,
    reserveVaultSol,
    setReserveVaultSol,
    bots, 
    setBots, 
    botLogs, 
    botLearnings, 
    setBotLearnings, 
    closedPositions, 
    setTransactions,
    resetDemoData,
    isLoading 
  } = useAppState();

  const handleClaimBotProfit = (botId: string) => {
    const targetBot = bots.find(b => b.id === botId);
    if (!targetBot) return;

    const profitToClaim = typeof targetBot.netProfit === 'number' && !isNaN(targetBot.netProfit) && targetBot.netProfit > 0
      ? targetBot.netProfit 
      : (typeof targetBot.pnl === 'number' && !isNaN(targetBot.pnl) && targetBot.pnl > 0 ? targetBot.pnl : 0);

    if (profitToClaim <= 0) {
      alert("Aucun gain à encaisser pour ce robot.");
      return;
    }

    const isRealMode = (targetBot.mode || tradingMode) === 'REAL';
    const currency = isRealMode ? 'SOL' : '$';

    if (confirm(`Voulez-vous encaisser et transférer +${profitToClaim.toFixed(2)} ${currency} de gains générés par "${targetBot.strategy}" vers votre solde / Wallet Phantom ?`)) {
      if (isRealMode) {
        if (typeof window !== 'undefined') {
          window.dispatchEvent(new Event('web3_wallet_updated'));
        }
        const skimSol = profitToClaim * 0.10;
        if (setReserveVaultSol) {
          setReserveVaultSol(prev => (Number(prev) || 0) + skimSol);
        }
      } else {
        setBalance(prev => prev + profitToClaim);
        const skimUsd = profitToClaim * 0.10;
        if (setReserveVault) {
          setReserveVault(prev => (Number(prev) || 0) + skimUsd);
        }
      }

      setBots(prev => prev.map(b => {
        if (b.id === botId) {
          return {
            ...b,
            netProfit: 0,
            pnl: 0
          };
        }
        return b;
      }));

      const newTx = {
        id: 'tx_claim_' + Math.random().toString(36).substring(2, 9),
        type: 'CLAIM',
        amount: profitToClaim,
        currency: currency,
        status: 'COMPLETED',
        timestamp: Date.now(),
        description: `Encaissement des bénéfices du bot ${targetBot.strategy}`
      };
      if (setTransactions) {
        setTransactions(prev => [newTx, ...(prev || [])]);
      }

      addBotLog(
        botId, 
        targetBot.strategy, 
        `[ENCAISSEMENT RÉUSSI] Gains de +${profitToClaim.toFixed(2)} ${currency} transférés vers votre solde & Wallet Phantom avec succès !`, 
        'trade'
      );

      if (typeof window !== 'undefined') {
        window.dispatchEvent(new Event('web3_wallet_updated'));
      }

      alert(`✅ Succès ! +${profitToClaim.toFixed(2)} ${currency} ont été encaissés et transférés vers votre solde / Wallet Phantom !`);
    }
  };

  const handleClaimAllProfits = () => {
    const botsWithProfits = filteredBots.filter(b => (b.netProfit || b.pnl || 0) > 0);
    if (botsWithProfits.length === 0) {
      alert("Aucun gain à encaisser pour le moment.");
      return;
    }

    const totalProfitToClaim = botsWithProfits.reduce((sum, b) => sum + (b.netProfit || b.pnl || 0), 0);
    const currency = tradingMode === 'REAL' ? 'SOL' : '$';

    if (confirm(`Voulez-vous encaisser TOUS les gains des bots (+${totalProfitToClaim.toFixed(2)} ${currency}) vers votre solde / Wallet Phantom ?`)) {
      if (tradingMode === 'REAL') {
        if (typeof window !== 'undefined') {
          window.dispatchEvent(new Event('web3_wallet_updated'));
        }
        const skimSol = totalProfitToClaim * 0.10;
        if (setReserveVaultSol) {
          setReserveVaultSol(prev => (Number(prev) || 0) + skimSol);
        }
      } else {
        setBalance(prev => prev + totalProfitToClaim);
        const skimUsd = totalProfitToClaim * 0.10;
        if (setReserveVault) {
          setReserveVault(prev => (Number(prev) || 0) + skimUsd);
        }
      }

      const botIdsToReset = new Set(botsWithProfits.map(b => b.id));
      setBots(prev => prev.map(b => {
        if (botIdsToReset.has(b.id)) {
          return {
            ...b,
            netProfit: 0,
            pnl: 0
          };
        }
        return b;
      }));

      const newTx = {
        id: 'tx_claim_all_' + Math.random().toString(36).substring(2, 9),
        type: 'CLAIM',
        amount: totalProfitToClaim,
        currency: currency,
        status: 'COMPLETED',
        timestamp: Date.now(),
        description: `Encaissement global des bénéfices de tous les bots`
      };
      if (setTransactions) {
        setTransactions(prev => [newTx, ...(prev || [])]);
      }

      if (typeof window !== 'undefined') {
        window.dispatchEvent(new Event('web3_wallet_updated'));
      }

      alert(`✅ Succès ! +${totalProfitToClaim.toFixed(2)} ${currency} de gains globaux ont été encaissés sur votre solde / Wallet Phantom !`);
    }
  };

  const isReal = tradingMode === 'REAL';
  const rawBalance = isReal ? (solanaBalance || 0) : balance;
  const currentReserveVault = isReal ? (Number(reserveVaultSol) || 0) : (Number(reserveVault) || 0);
  const allocatableBalance = Math.max(0, rawBalance - currentReserveVault);

  // New Bot Form State
  const [botPair, setBotPair] = useState<string>('ALL');
  const [botStrategy, setBotStrategy] = useState<'RSI Pullback' | 'EMA Cross' | 'BB Mean Reversion' | 'SuperTrend Momentum' | 'VWAP Breakout' | 'AI Autopilot (Machine à Cash)' | 'Pump.fun Sniper Bot'>('AI Autopilot (Machine à Cash)');
  const [botTimeframe, setBotTimeframe] = useState<string>('15');
  const [botCapital, setBotCapital] = useState<number>(() => isReal ? 0.5 : 1000);
  const [botRiskProfile, setBotRiskProfile] = useState<'CONSERVATIVE' | 'MODERATE' | 'AGGRESSIVE'>('MODERATE');
  const [pumpSniperMode, setPumpSniperMode] = useState<'PRECOCE' | 'MOMENTUM' | 'RAYDIUM'>('PRECOCE');
  const [priorityFee, setPriorityFee] = useState<number>(0.005);
  const [autoVolume, setAutoVolume] = useState<boolean>(false);
  const [botCustomRules, setBotCustomRules] = useState<string>('');

  React.useEffect(() => {
    if (tradingMode === 'REAL' && botCapital === 1000) {
      setBotCapital(0.5);
    } else if (tradingMode === 'DEMO' && botCapital === 0.5) {
      setBotCapital(1000);
    }
  }, [tradingMode]);

  const handleStartBot = (e: React.FormEvent) => {
    e.preventDefault();
    if (botCapital <= 0) {
      alert("Le capital du bot doit être supérieur à 0.");
      return;
    }

    if (tradingMode === 'REAL') {
      if (solanaBalance === null || botCapital > allocatableBalance) {
        alert(`Solde SOL allocable insuffisant. Requis: ${botCapital} SOL, Capital allocable (hors Coffre-Fort SOL): ${allocatableBalance.toFixed(3)} SOL (Coffre-Fort protégé: ${currentReserveVault.toFixed(3)} SOL).`);
        return;
      }
    } else {
      if (botCapital > allocatableBalance) {
        alert(`Capital insuffisant pour le bot. Requis: ${botCapital} $, Capital allocable (hors Coffre-Fort de Réserve 10%): $${allocatableBalance.toFixed(2)}. Le coffre-fort ($${currentReserveVault.toFixed(2)}) est intouchable et protégé.`);
        return;
      }
    }

    const newBot = {
      id: 'bot_' + Math.random().toString(36).substring(2, 9),
      pair: botStrategy === 'AI Autopilot (Machine à Cash)' 
        ? 'ALL' 
        : botStrategy === 'Pump.fun Sniper Bot'
          ? 'SOL:MEME'
          : botPair,
      strategy: botStrategy,
      timeframe: botStrategy === 'Pump.fun Sniper Bot' ? '0' : botTimeframe,
      capital: botCapital,
      status: 'RUNNING',
      createdAt: Date.now(),
      totalTrades: 0,
      winningTrades: 0,
      consecutiveLosses: 0,
      netProfit: 0,
      selectivityMultiplier: 1.0,
      riskProfile: botStrategy === 'AI Autopilot (Machine à Cash)' ? botRiskProfile : undefined,
      pumpMode: botStrategy === 'Pump.fun Sniper Bot' ? pumpSniperMode : undefined,
      priorityFee: botStrategy === 'Pump.fun Sniper Bot' ? priorityFee : undefined,
      autoVolume: botStrategy === 'Pump.fun Sniper Bot' ? autoVolume : undefined,
      mode: tradingMode,
      customRules: botCustomRules || undefined
    };

    setBots(prev => {
      if (prev.some(x => x.id === newBot.id)) return prev;
      return [...prev, newBot];
    });

    setBotCustomRules('');

    if (tradingMode === 'REAL') {
      if (typeof window !== 'undefined') {
        window.dispatchEvent(new Event('web3_wallet_updated'));
      }
      addBotLog(newBot.id, newBot.strategy, `Sniper Bot Solana démarré en réel avec ${newBot.capital} SOL de capital allocation.`, 'info');
    } else {
