                      const oldPrice = livePrices[pairVal];
                      if (oldPrice) {
                        newDirections[pairVal] = dexPriceSol > oldPrice ? 'up' : dexPriceSol < oldPrice ? 'down' : 'flat';
                      }
                      return;
                    }
                  }
